def solve(tokens):
    """Evaluate an expression given in Reverse Polish Notation.
    The tokens are strings representing integers or the operators '+', '-', '*', '/'.
    Division truncates toward zero, matching the typical behavior of integer division in many
    programming languages (e.g., C/C++). The function returns the integer result.
    """
    if not tokens:
        raise ValueError("Empty token list")
    stack = []
    for token in tokens:
        if token in {"+", "-", "*", "/"}:
            if len(stack) < 2:
                raise ValueError("Insufficient operands for operator")
            b = stack.pop()
            a = stack.pop()
            if token == "+":
                res = a + b
            elif token == "-":
                res = a - b
            elif token == "*":
                res = a * b
            else:  # token == "/"
                # Perform division that truncates toward zero.
                # Using int(a / b) achieves this because Python's true division returns a float.
                # For positive numbers this equals floor division, for negative numbers it
                # truncates toward zero as required.
                if b == 0:
                    raise ZeroDivisionError("division by zero in RPN expression")
                res = int(a / b)
            stack.append(res)
        else:
            # token should be an integer literal
            stack.append(int(token))
    if len(stack) != 1:
        raise ValueError("Invalid RPN expression – leftover operands")
    return stack[0]

