def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses an O(n log n) patience sorting algorithm.
    """
    import bisect
    tails = []  # tails[i] = smallest possible tail of an inc subseq of length i+1
    for x in nums:
        # Find insertion point (first element >= x) for strict increase we use bisect_left
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

