def solve(path: str) -> str:
    """Simplify an absolute Unix file path.
    Resolve '.' and '..' components, collapse multiple slashes, and remove any trailing slash.
    The result always starts with '/' and represents the canonical path.
    """
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            # Skip empty components caused by consecutive slashes or '.'
            continue
        if part == '..':
            if stack:
                stack.pop()
            # If stack empty, we stay at root; nothing to pop.
        else:
            stack.append(part)
    # Join the components with '/' and ensure leading '/'
    simplified = '/' + '/'.join(stack)
    return simplified

