def solve(meetings):
    """Return the maximum number of non‑overlapping meetings that can be attended.
    Accepts meetings where start may be greater than end; such intervals are normalized.
    """
    if not meetings:
        return 0
    norm = []
    for iv in meetings:
        if not iv:
            continue
        s, e = iv[0], iv[1]
        if s > e:
            s, e = e, s
        norm.append([s, e])
    if not norm:
        return 0
    # Greedy by earliest end time
    norm.sort(key=lambda x: (x[1], x[0]))
    count = 0
    current_end = -float('inf')
    for s, e in norm:
        if s >= current_end:
            count += 1
            current_end = e
    return count

