def solve(coins, amount):
    """Return the minimum number of coins needed to make *amount*.
    *coins* is a list of positive integers (coin denominations). You have an
    unlimited supply of each coin. If the amount cannot be formed, return -1.
    """
    # Edge cases
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Remove non‑positive coin values, as they are not useful.
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    # DP array where dp[i] is the min coins to make i, initialized to a large number.
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for c in coins:
            if c <= i:
                if dp[i - c] + 1 < dp[i]:
                    dp[i] = dp[i - c] + 1
    return dp[amount] if dp[amount] != INF else -1

def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses patience sorting with binary search, O(n log n).
    """
    import bisect
    tails = []
    for x in nums:
        # find position to replace in tails
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

