def solve(grid):
    """Count islands in a grid of 0s and 1s.
    The grid may be jagged (rows of different lengths). Cells are adjacent
    horizontally and vertically.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def bfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if i < 0 or i >= rows:
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if (i, j) in visited or grid[i][j] == 0:
                continue
            visited.add((i, j))
            stack.append((i-1, j))
            stack.append((i+1, j))
            stack.append((i, j-1))
            stack.append((i, j+1))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and (i, j) not in visited:
                bfs(i, j)
                count += 1
    return count

