def solve(a, x):
    """Return the leftmost insertion index for x in sorted list a.
    Uses binary search to find the first position where a[pos] >= x.
    """
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

def solve(n: int) -> int:
    """Return the number of prime numbers strictly less than *n*.
    Uses the Sieve of Eratosthenes.
    """
    if n <= 2:
        return 0
    limit = n
    sieve = bytearray(b'\x01') * limit
    sieve[0:2] = b'\x00\x00'
    import math
    for p in range(2, int(math.isqrt(limit - 1)) + 1):
        if sieve[p]:
            step = p
            start = p * p
            sieve[start:limit:step] = b'\x00' * ((limit - 1 - start) // step + 1)
    return sum(sieve)

